// Generate safe inputs respecting printf-style constraints.
std::string whoami = FUZZ_PARAM_STR();
long code = (long)(*FUZZ_PARAM(unsigned long));
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;

// Choose a format that matches provided arguments to avoid UB.
if (choice == 0) {
    const char *fmt = "static message"; // no variadic args
    com_err(whoami.c_str(), code, fmt);
} else if (choice == 1) {
    const char *fmt = "msg=%s";
    std::string s = FUZZ_PARAM_STR();
    com_err(whoami.c_str(), code, fmt, s.c_str());
} else {
    const char *fmt = "num=%d hex=%x";
    int a = (int)(*FUZZ_PARAM(unsigned int));
    unsigned int b = *FUZZ_PARAM(unsigned int);
    com_err(whoami.c_str(), code, fmt, a, b);
}
// Validation: We ensure fmt and its arguments match, and avoid NULL for whoami/fmt.

